import {readFile,readdir,writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
const root=fileURLToPath(new URL('../',import.meta.url));const files={};
async function add(relative){files[relative]=await readFile(path.join(root,relative),'utf8');}
async function walk(dir){for(const e of await readdir(path.join(root,dir),{withFileTypes:true})){if(e.name.startsWith('.')||e.name.includes('.private.')||e.name.includes('.generated.'))continue;const relative=dir+'/'+e.name;if(e.isDirectory())await walk(relative);else if(/\.(ts|js|mjs|json|jsonc|md|ps1|html)$/.test(e.name))await add(relative);}}
for(const file of ['README.md','package.json','package-lock.json','tsconfig.json','wrangler.jsonc']){try{await add(file);}catch(e){if(e.code!=='ENOENT')throw e;}}
for(const dir of ['src','connector','scripts','docs','tests']){try{await walk(dir);}catch(e){if(e.code!=='ENOENT')throw e;}}
try{files['LICENSE']=await readFile(path.join(root,'LICENSE'),'utf8');}catch(e){if(e.code!=='ENOENT')throw e;files['LICENSE']=await readFile(path.join(root,'../LICENSE'),'utf8');}
const bundle={format:'rivule-corresponding-source-v1',license:'AGPL-3.0-only',usage:'Write each files entry to its relative path in an empty directory. Run npm ci --ignore-scripts; npm run check; npm test; npm run build. The production entrypoint is src/worker.ts; tests/runtime-worker.ts is local-only.',files};
await writeFile(path.join(root,'src/source.generated.ts'),'// Generated by scripts/source-bundle.mjs; contains source files only, never runtime data.\nexport const sourceBundle='+JSON.stringify(bundle)+';\n','utf8');
console.log('Prepared corresponding-source download ('+Object.keys(files).length+' files).');
